import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { useOSStore } from '../store/useOSStore';
import { GripHorizontal, Sparkles, AlertTriangle, ShieldCheck, Share2, Award, Zap, Database } from 'lucide-react';

export default function BulletinWidget() {
  const [isGlitched, setIsGlitched] = useState(false);
  const [statusMessage, setStatusMessage] = useState('');
  const [isMinimized, setIsMinimized] = useState(false);

  const addCredits = useOSStore((s) => s.addCredits);
  const addXP = useOSStore((s) => s.addXP);

  const triggerGlitch = () => {
    setIsGlitched(true);
    setStatusMessage('⚠️ PRISM CORRUPTION SPIKE DETECTED! SCANNING VEIL...');
    setTimeout(() => setIsGlitched(false), 1800);
  };

  const handleCheckIn = () => {
    addCredits(100);
    addXP(50);
    setStatusMessage('✨ Checked in at Cyacademy Bulletin Node! +100 Credits, +50 XP');
    setTimeout(() => setStatusMessage(''), 4000);
  };

  const handleSyncSquad = () => {
    setStatusMessage('⚡ Squad Synced: 4 Operatives Active on Mesh Network.');
    setTimeout(() => setStatusMessage(''), 4000);
  };

  return (
    <motion.div
      drag
      dragMomentum={false}
      initial={{ scale: 0.96, opacity: 0, y: 10 }}
      animate={{ scale: 1, opacity: 1, y: 0 }}
      transition={{ duration: 0.3 }}
      className={`relative z-20 w-full max-w-4xl rounded-3xl border-2 transition-all duration-300 shadow-[0_20px_50px_rgba(157,140,210,0.35)] backdrop-blur-2xl select-none overflow-hidden ${
        isGlitched
          ? 'border-pink-500 bg-pink-950/90 text-white filter invert contrast-200 hue-rotate-180 animate-pulse'
          : 'border-purple-300/80 bg-white/80 text-slate-900'
      }`}
    >
      {/* Background Soft Shimmer Overlay */}
      <div className="absolute inset-0 bg-gradient-to-br from-purple-100/40 via-white/20 to-cyan-100/40 pointer-events-none" />

      {/* ------------------------------------------------------------------ */}
      {/* HEADER DRAG BAR                                                    */}
      {/* ------------------------------------------------------------------ */}
      <div className="relative z-10 flex items-center justify-between border-b border-purple-200/60 bg-[#ECE5F9]/80 px-4 py-2.5 cursor-grab active:cursor-grabbing">
        <div className="flex items-center gap-2.5 font-bold text-purple-950 tracking-wider text-xs">
          <GripHorizontal size={18} className="text-purple-600/80" />
          <Sparkles size={15} className="text-purple-600 animate-spin" />
          <span className="font-serif-y2k text-sm font-extrabold tracking-wide">CYACADEMY BULLETIN NODE</span>
        </div>

        {/* Real-time Status Pill & Window Controls */}
        <div className="flex items-center gap-3 text-[11px] font-medium text-slate-700">
          <div className="flex items-center gap-2 rounded-full bg-white/80 px-3 py-1 border border-purple-200 shadow-sm">
            <span>Time: <strong className="text-purple-950 font-bold">Evening</strong></span>
            <span className="text-slate-300">•</span>
            <span>Veil: <strong className={isGlitched ? 'text-pink-600 animate-bounce' : 'text-cyan-700'}>Flicker</strong></span>
            <span className="text-slate-300">•</span>
            <span>House: <strong className="text-purple-700">Vector</strong></span>
            <span className="text-slate-300">•</span>
            <span>Role: <strong className="text-pink-600">Anti</strong></span>
          </div>

          <button
            onClick={() => setIsMinimized((prev) => !prev)}
            className="flex h-6 w-6 items-center justify-center rounded-full bg-purple-200/70 hover:bg-purple-300 text-purple-950 font-bold transition shadow-sm"
            title={isMinimized ? 'Expand Board' : 'Minimize Board'}
          >
            {isMinimized ? '＋' : '−'}
          </button>
        </div>
      </div>

      {!isMinimized && (
        <div className="p-4 space-y-3.5">
          {statusMessage && (
            <div className="rounded-xl border border-purple-300 bg-purple-100/90 p-2.5 text-center text-xs font-bold text-purple-950 shadow-sm animate-fade-in">
              {statusMessage}
            </div>
          )}

          {/* ------------------------------------------------------------------ */}
          {/* 3-COLUMN CREATIVE Y2K PASTEL GLASS CARDS                           */}
          {/* ------------------------------------------------------------------ */}
          <div className="grid grid-cols-1 gap-3.5 md:grid-cols-3">
            {/* COLUMN 1: CAMPUS FEED (Soft Lavender Glass) */}
            <div className="flex flex-col space-y-2.5 rounded-2xl border border-purple-200/90 bg-[#F4EFFF]/90 p-3.5 shadow-sm hover:shadow-md transition">
              <div className="flex items-center justify-between border-b border-purple-200 pb-1.5 font-bold text-purple-950 text-xs">
                <span className="flex items-center gap-1.5">
                  <span className="h-2 w-2 rounded-full bg-purple-500" />
                  CAMPUS FEED
                </span>
                <span className="rounded-full bg-purple-200/80 px-2 py-0.5 text-[9px] text-purple-800 font-semibold">
                  Live Node
                </span>
              </div>

              {/* Class Updates */}
              <div className="rounded-xl border border-purple-200 bg-white/95 p-2.5 space-y-1 shadow-sm">
                <div className="font-bold text-purple-950 text-xs flex items-center gap-1.5">
                  <Award size={13} className="text-purple-600" /> Class Updates
                </div>
                <div className="text-slate-800 font-semibold text-[11px]">Syntax HW: Quantum Recursion</div>
                <div className="text-slate-500 text-[10px]">Aethercore Lab 4 Open until 22:00</div>
              </div>

              {/* Clubs & Social */}
              <div className="rounded-xl border border-purple-200 bg-white/95 p-2.5 space-y-1 shadow-sm">
                <div className="font-bold text-purple-950 text-xs flex items-center gap-1.5">
                  <Sparkles size={13} className="text-violet-600" /> Clubs & Social
                </div>
                <div className="text-slate-800 font-semibold text-[11px]">Netrunner Art Club @ 19:00</div>
                <div className="text-slate-500 text-[10px]">Robotics Build: Graviton Rig</div>
              </div>

              {/* Pulse Trending */}
              <div className="rounded-xl border border-purple-200 bg-white/95 p-2.5 space-y-1 shadow-sm">
                <div className="font-bold text-purple-950 text-xs flex items-center gap-1.5">
                  <Zap size={13} className="text-amber-500" /> Pulse Trending
                </div>
                <div className="flex gap-2">
                  <span className="rounded-full bg-purple-100 px-2 py-0.5 text-[10px] font-bold text-purple-700">#DormDrama</span>
                  <span className="rounded-full bg-cyan-100 px-2 py-0.5 text-[10px] font-bold text-cyan-700">#OddSighting</span>
                </div>
              </div>
            </div>

            {/* COLUMN 2: MISSIONS & OPS (Soft Mint Glass) */}
            <div className="flex flex-col space-y-2.5 rounded-2xl border border-emerald-200/90 bg-[#E6F9F5]/90 p-3.5 shadow-sm hover:shadow-md transition">
              <div className="flex items-center justify-between border-b border-emerald-200 pb-1.5 font-bold text-emerald-950 text-xs">
                <span className="flex items-center gap-1.5">
                  <span className="h-2 w-2 rounded-full bg-emerald-500" />
                  MISSIONS & OPS
                </span>
                <span className="rounded-full bg-emerald-200/80 px-2 py-0.5 text-[9px] text-emerald-800 font-semibold">
                  PRISM Spike
                </span>
              </div>

              {/* DGA Alerts */}
              <div className="rounded-xl border border-red-200 bg-red-50/95 p-2.5 space-y-1 shadow-sm">
                <div className="font-bold text-red-700 text-xs flex items-center gap-1.5">
                  <AlertTriangle size={13} className="text-red-500" /> DGA Alerts
                </div>
                <div className="text-red-900 font-bold text-[11px]">⚠️ Perimeter Breach Alert</div>
                <div className="text-red-700/80 text-[10px]">Patrol Route: Sector 7 Subnet</div>
              </div>

              {/* Career Tasks */}
              <div className="rounded-xl border border-emerald-200 bg-white/95 p-2.5 space-y-1 shadow-sm">
                <div className="font-bold text-emerald-950 text-xs flex items-center gap-1.5">
                  <ShieldCheck size={13} className="text-emerald-600" /> Career Tasks
                </div>
                <div className="text-slate-800 font-semibold text-[11px]">Faith Medical Intake Clearance</div>
                <div className="text-slate-500 text-[10px]">Archive Scan: Mireth Records</div>
              </div>

              {/* PRISM Activity */}
              <div className="rounded-xl border border-pink-300 bg-pink-50/95 p-2.5 space-y-1 shadow-sm">
                <div className="font-bold text-pink-950 text-xs flex items-center justify-between">
                  <span className="flex items-center gap-1.5">
                    <span className="h-2 w-2 rounded-full bg-pink-500 animate-ping" />
                    PRISM Activity
                  </span>
                  <span className="text-[9px] uppercase px-1.5 py-0.5 rounded-full bg-pink-200 text-pink-800 font-bold">
                    Corrupted
                  </span>
                </div>
                <div className="text-pink-700 font-bold font-mono text-[11px]">Corruption Level ↑ 14.8%</div>
                <div className="text-slate-600 text-[10px]">App Lockdown: Sector 9 Mesh</div>
              </div>
            </div>

            {/* COLUMN 3: SIGNALS & LORE (Soft Rose Glass) */}
            <div className="flex flex-col space-y-2.5 rounded-2xl border border-pink-200/90 bg-[#FDF0F6]/90 p-3.5 shadow-sm hover:shadow-md transition">
              <div className="flex items-center justify-between border-b border-pink-200 pb-1.5 font-bold text-pink-950 text-xs">
                <span className="flex items-center gap-1.5">
                  <span className="h-2 w-2 rounded-full bg-pink-500" />
                  SIGNALS & LORE
                </span>
                <span className="rounded-full bg-pink-200/80 px-2 py-0.5 text-[9px] text-pink-800 font-semibold">
                  Veil Motes
                </span>
              </div>

              {/* City Anomalies */}
              <div className="rounded-xl border border-amber-200 bg-amber-50/95 p-2.5 space-y-1 shadow-sm">
                <div className="font-bold text-amber-900 text-xs flex items-center gap-1.5">
                  <Zap size={13} className="text-amber-600" /> City Anomalies
                </div>
                <div className="text-slate-800 font-semibold text-[11px]">Glassline Flicker in Sprawl</div>
                <div className="text-slate-600 text-[10px]">Sub-Aureline Frequency Hum</div>
              </div>

              {/* Aethercore Echoes (Redacted Text) */}
              <div className="rounded-xl border border-pink-200 bg-white/95 p-2.5 space-y-1 shadow-sm">
                <div className="font-bold text-pink-950 text-xs flex items-center gap-1.5">
                  <Share2 size={13} className="text-pink-600" /> Aethercore Echoes
                </div>
                <div className="text-purple-900 font-semibold font-mono text-[11px]">Fragment #07: "Protocol Unread"</div>
                <div className="rounded-lg bg-slate-900 p-1.5 font-mono text-pink-400 text-[10px] tracking-widest text-center shadow-inner">
                  [ ████████████████ ]
                </div>
              </div>

              {/* Lineage Keys */}
              <div className="rounded-xl border border-purple-200 bg-white/95 p-2.5 space-y-1 shadow-sm">
                <div className="font-bold text-purple-950 text-xs flex items-center gap-1.5">
                  <Award size={13} className="text-amber-500" /> Lineage Keys
                </div>
                <div className="text-slate-800 font-semibold text-[11px]">Celestial Glyph Activated</div>
                <div className="text-purple-800 font-bold text-[10px]">Mark: "Seraphima Lineage"</div>
              </div>
            </div>
          </div>

          {/* ------------------------------------------------------------------ */}
          {/* ACTION BUTTON FOOTER BAR                                           */}
          {/* ------------------------------------------------------------------ */}
          <div className="flex flex-wrap items-center justify-between gap-2 rounded-2xl border border-purple-200/80 bg-[#ECE5F9]/90 p-2.5 shadow-sm">
            <div className="flex flex-wrap items-center gap-2 text-xs">
              <button
                onClick={handleCheckIn}
                className="flex items-center gap-1.5 rounded-xl border border-emerald-300 bg-emerald-100/90 px-3.5 py-1.5 font-bold text-emerald-950 hover:bg-emerald-200 transition shadow-sm"
              >
                <Award size={14} className="text-emerald-700" /> [ CHECK IN ]
              </button>

              <button
                onClick={handleSyncSquad}
                className="flex items-center gap-1.5 rounded-xl border border-cyan-300 bg-cyan-100/90 px-3.5 py-1.5 font-bold text-cyan-950 hover:bg-cyan-200 transition shadow-sm"
              >
                <Zap size={14} className="text-cyan-700" /> [ SYNC SQUAD ]
              </button>

              <button
                onClick={triggerGlitch}
                className="flex items-center gap-1.5 rounded-xl border border-pink-400 bg-pink-500/20 px-3.5 py-1.5 font-bold text-pink-950 hover:bg-pink-500/40 transition shadow-sm animate-pulse"
              >
                <Sparkles size={14} className="text-pink-600" /> [ SCAN VEIL ]
              </button>

              <button
                onClick={() => {
                  setStatusMessage('📡 Pulse update shared to Cyacademy Mesh Network.');
                  setTimeout(() => setStatusMessage(''), 3000);
                }}
                className="flex items-center gap-1.5 rounded-xl border border-purple-300 bg-purple-100/90 px-3.5 py-1.5 font-bold text-purple-950 hover:bg-purple-200 transition shadow-sm"
              >
                <Share2 size={14} className="text-purple-700" /> [ PULSE SHARE ]
              </button>
            </div>

            <button
              onClick={() => {
                setStatusMessage('📜 Cyacademy Logs archived to miraverseDb.');
                setTimeout(() => setStatusMessage(''), 3000);
              }}
              className="flex items-center gap-1.5 rounded-xl border border-amber-300 bg-amber-100/90 px-3.5 py-1.5 font-bold text-amber-950 hover:bg-amber-200 transition shadow-sm text-xs"
            >
              <Database size={14} className="text-amber-700" /> [ ARCHIVE LOGS ]
            </button>
          </div>
        </div>
      )}
    </motion.div>
  );
}
